"xjyq13": "Acro: os sticks são taxas de giro, ao soltar ele mantém a atitude. Angle: os sticks são inclinação até o limite de 60 graus do Betaflight, ao soltar ele nivela. Esta corrida é voada no teclado, que guarda a própria escolha (Corridas no teclado, em Quad); esta linha muda essa. M durante o voo também troca.",
"1r5ubv6": "Acro: os sticks são taxas de giro, ao soltar ele mantém a atitude. Angle: os sticks são inclinação até o limite de 60 graus do Betaflight, ao soltar ele nivela, e o yaw continua sendo taxa. Flips e rolls precisam de Acro. M durante o voo também troca, e mantém.",
"x7vih9": "Quantos de cada lado, como os bots jogam e quando acaba.",
"17g8v9b": "Continue voando aqui sozinho, sem bots e sem relógio.",
"11br69w": "Bots, e como eles filmam.",
"m20i5w": "Continue filmando aqui sozinho, sem bots.",
"c8vuhg": "A sala de espera: os bots, o nível de cada um, a rodada e a vantagem inicial.",
"5typne": "Voe a escola sozinho, sem bots.",
"1afdza": "Bots, como eles pastoreiam e quando a rodada acaba.",
"1t8ovw1": "Continue pastoreando aqui sozinho, sem bots e sem relógio.",
"1087r08": "Bots, o nível deles, o comprimento das fitas e a rodada.",
"1206cs3": "Continue voando aqui sem fitas e sem bots.",
"899bgs": "Bots, o nível deles, a rodada e a força dos acertos.",
"172ev2t": "Continue voando aqui sem armas e sem bots.",
"1w5pf1h": "Botões de canhão e míssil",
"14d24dx": "Escolha um botão ou chave para cada um e teste.",
"d2okc9": "Voltar aos Minijogos",
"j88ayy": "Continuar",
"jsscfj": "Parece errado?",
"1emvcwj": "Até onde os sticks vão, e o limite do acelerador. Mudar aqui deixa o quad onde está e o relógio correndo.",
"17lkkrv": "Outros",
"1sc5qgc": "Seu nome, seu rádio, gráficos e som.",
"6gxuho": "Encerra {0}.",
"wyh1np": "O quanto o quad parece pesado. Para a direita fica mais pesado: ele cai quando você corta o acelerador e para de ficar pendurado no topo de um salto. Para a esquerda fica mais leve e flutua. {0} é o quad como ele vem; mudar no meio da volta anula a volta, e uma volta voada fora de {1} vai para o quadro público com o peso ao lado do seu nome.",
"1ayl725": "Aderência ao ar",
"6bttpz": "O quanto o ar segura o quad, ou seja, o quanto ele desliza com os sticks centrados. Para a esquerda ele segue deslizando e anda mais rápido; para a direita o ar o agarra, ele para antes e a velocidade máxima cai. {0} é o quad como ele vem, definido a partir dos ajustes que os pilotos enviaram. Mudar no meio da volta anula a volta, e uma volta voada fora de {1} vai para o quadro público com a etiqueta Tuned.",
"ior56v": "Potência dos motores",
"1x4irmq": "Quanta velocidade os motores fazem por volt, o KV deles. Para a esquerda é mais suave: um punch mais gentil e velocidade máxima menor. Para a direita é mais forte, a bateria cai mais por isso e o quad paira mais baixo no stick. {0} é o quad como ele vem, definido a partir dos ajustes que os pilotos enviaram. Mudar no meio da volta anula a volta, e uma volta voada fora de {1} vai para o quadro público com a etiqueta Tuned.",
"1bsvonq": "Desligado por padrão. Ligado, {0} se juntam a Peso entre os sticks enquanto o quad está no chão, e um voo com os seus próprios controles termina com uma pergunta: foi melhor que o quad padrão? Nada é enviado a não ser que você diga sim. Desligado, o quad voa como ele vem, não importa o que os controles digam. Trocar no meio da volta anula a volta se mudar o quad que você está voando.",
"5xvgod": "Perguntar depois de um voo ajustado",
"1siorg1": "Quando um voo com os seus próprios controles termina, pergunta se foi melhor que o padrão. Você sempre pode responder não, e nada é enviado sem um sim. Desligado, nunca pergunta; os controles continuam funcionando.",
"187fv0s": "Conte ao trabalho de ajuste como o quad voa. Uma palavra basta; seu ajuste, o ajuste de PID e os rates vão junto.",
"16us7mj": "Idioma",
"2nnvct": "O idioma dos menus. O jogo reinicia para aplicar.",
"1hmyggy": "{0} foi testado nesta máquina e não manteve a imagem em dia, então o Auto fica em {1} ou abaixo.",
"s4dnb5": "Auto: desenhando em {0}{1}. Ele observa como os quadros realmente chegam, baixa a resolução quando a imagem atrasa e muda a predefinição entre rodadas.{2} Escolha uma predefinição para fixar na mão.",
"1ejndm0": "Gráficos",
"dcm8ea": "Desenha cada quadro direto na tela em vez de colocá-lo na fila atrás da página, o que pode tirar um ou dois quadros do tempo entre os sticks e a imagem. Pode causar tearing.",
"1ttxrpl": "Desligado a partir do próximo carregamento. {0} Este navegador continua usando até você recarregar.",
"1j0ql37": "Desligado. {0} Recarregue depois de ligar.",
"o73nnv": "A edição Steam pode rodar com vsync desligado.",
"101as9w": "a tela atualiza a {0} Hz",
"cfutp1": "a GPU leva cerca de {0} ms a mais por quadro",
"gtjdfs": "A visualização de baixa latência está em uso",
"1ampkwb": "Se este monitor consegue passar de 60 Hz, confira se o sistema está na taxa de atualização máxima (Windows: Configurações, Tela, Tela avançada), porque a página só consegue desenhar na mesma frequência da tela que recebe.",
"13d5h9g": "Da entrada à tela",
"9anx43": "Não dá para medir aqui",
"57y603": "Aperte algumas teclas",
"ks1elk": "Cerca de {0} ms",
"12jryem": "Detectando",
"h5se6q": "Lido do contexto WebGL que desenha o mundo.",
"jgkrww": "Conecte um rádio em modo joystick. Se houver mais de um conectado, é aqui que você escolhe qual voa.",
"1y6zyev": "Um dispositivo está conectado, {0}. Abra aqui para confirmar ou para trocar para o teclado.",
"1a5n4iv": "{0} dispositivos estão conectados. Mexa o que você quer. O Windows lista na ordem dos Controladores de jogo; é nesta tela que você escolhe.",
"hkrgl0": "Uma pista com portões em um campo ao ar livre, contra o relógio. Um quad de corrida grande e rápido, e cada volta que você terminar pode ir para o quadro público.",
"1rnl54t": "O mesmo relógio, em ambiente fechado. Um whoop minúsculo com dutos em uma pista que cabe em uma sala de estar.",
"1kaa7l9": "Todos os mapas de freestyle: a cidade, as casas de Nick Burns, Heads e Joshua Bardwell, Thomas More's Shop, Sunnyfield, Shiokaze Point, Hibari Yard, e todos os mapas que os pilotos construíram e publicaram no quadro. Sem relógio, sem portões, e os nomes de manobras são uma chave lá dentro.",
"tn5ckg": "Editor",
"19ybx9k": "Faça o seu. Uma pista de corrida para o cinco polegadas, uma sala para o whoop ou um mapa de freestyle com prédios abandonados, guindastes e vãos com nome, desenhado de cima e voado da mesma página.",
"1rjxeiy": "Do seu primeiro pairado até uma licença pro. Aprenda a voar, conquiste a Licença Novato e depois suba por uma árvore de habilidades em corrida ou freestyle. Comece aqui se você nunca voou.",
