"1uvpjn8": "Lista de manobras",
"10sqi3d": "Cada manobra que o pontuador sabe nomear, quanto ela paga e como ela é. Escolha uma e assista: o desenho vem da mesma definição que o pontuador usa para comparar, então o que você vê é exatamente o que ele espera. Cada uma foi voada e pontuada em testes, e é isso que garante um lugar aqui. Os pontos são antes do combo, que os multiplica.",
