"10nopfd": "Campo de visão",
"unl4q1": "Mais largo mostra mais, mais estreito amplia. Estreito imita o que uma lente FPV faz com o meio da imagem; Padrão devolve um pouco disso em troca de largura; O mais largo é o máximo que esta imagem consegue de forma honesta, e os portões vão parecer menores.",
"4emmbg": "Olho de peixe",
"1u80da4": "Curva a imagem como uma lente FPV de verdade: os cantos ficam onde o campo de visão os coloca, as bordas se apertam e o meio fica maior. Desligado é uma imagem reta, retilínea. Se visões largas dão enjoo, tente Leve ou Médio, e use um campo de visão mais largo para recuperar a largura.",
"1ir4yll": "Ângulo da câmera",
"6gsnw2": "O quanto a câmera aponta para cima em relação à estrutura. {0} é plano, olhando ao longo do nariz. {1} é um cruzeiro típico. 45 a {2} é corrida. Acima de uns 30, o yaw começa a inclinar o horizonte: a {3} graus, {4} por cento de um yaw aparece como roll na imagem. É o que uma câmera inclinada de verdade faz. Baixe a taxa máxima de yaw na tela de Rates para domar isso.",
"1vp9w8f": "O yaw vai inclinar o horizonte",
"1hjxoj1": "Com {0} graus de inclinação, {1} por cento de um yaw aparece como roll na imagem: {2} deg/s com a sua taxa de yaw de {3} deg/s. É o que uma câmera inclinada de verdade faz, e a resposta de sempre é um yaw mais lento. Baixar a taxa máxima de yaw para {4} traz de volta para {5} deg/s. Você pode mudar quando quiser na tela de Rates.",
"1f9wwkb": "Manter este relato?",
"v5eaek": "Você escreveu algo que não foi enviado. Nada aqui guarda rascunho, então fechar agora perde tudo.",
