"hqa4hr": "PIDs: como o ajuste vem",
"i1tfp3": "Peso {0}%, Aderência ao ar {1}%, Potência dos motores {2}%",
"7x3x2g": "Bateria {0} V por célula, lente {1} graus, inclinação {2}°",
"nnhdr0": "É para o {0}, então você passa para essa aeronave e para a classe de pistas dela.",
"1axqv1t": "Ele mexe em Aderência ao ar ou Potência dos motores, então o Ajuste da sensação de voo é ligado, e uma volta voada com ele vai para o quadro público com a etiqueta Tuned.",
"t9yl6f": "As configurações de Betaflight dele tomam o lugar de Suas edições nessa aeronave até você colocar as suas de volta.",
"f50exw": "Seus gráficos, sticks, rádio e tempos de volta não são alterados.",
"1e5r0vj": "Esta versão não consegue voar esse ajuste. Ele pode ser para uma aeronave adicionada depois.",
