"2qyb3f": "Como ele voa?",
"1x4knm": "Uma palavra sincera guia o trabalho de ajuste mais do que qualquer telemetria. Só a primeira linha é necessária; seu ajuste, o ajuste de PID e os rates vão junto com a resposta, para que os números por trás da sensação cheguem também. Você estava voando {0}.",
"1yc8yfn": "O controle de Peso entre os sticks na tela de voo é exatamente para essa queixa: ele escala o peso que o quad carrega, então ele cai quando você corta o acelerador em vez de ficar pendurado. O seu está em {0} por cento. Mais para a direita ele cai mais rápido quando você corta o acelerador e flutua menos depois de um punch curto. O pairado sobe no stick junto, de {1} por cento no padrão para {2} em {3}. Vale arrastar antes de esperar por nós, e uma volta voada assim vai para o quadro público com o peso ao lado do seu nome.",
"r74boy": "Este quad paira em {0} por cento do stick sem limite de acelerador, então quase todo o curso fica acima do pairado. Rates, Limite do acelerador, 75 por cento leva o pairado para {1} por cento e devolve o controle fino sem perder nenhuma subida que dê para usar em ambiente fechado. Vale tentar antes de esperar por nós.",
"1xpffsm": "Ligar o ajuste da sensação de voo",
"194uxup": "O ajuste da sensação de voo está ligado. Enquanto você está pousado, {0} {1} ao lado de Peso entre os sticks. Se uma configuração for melhor que a padrão, no fim do voo você é perguntado se quer enviar.",
"1elhpti": "Quer mudar você mesmo? O ajuste da sensação de voo coloca {0} ao lado de Peso enquanto você está no chão: {1}. Se uma configuração for melhor que a padrão, você pode nos enviar os números depois do voo. Desligado a menos que você ligue, e nada é enviado sem o seu sim.",
"15h6xkr": "Com suas palavras (opcional)",
