"yigmhv": "Esse ajuste está no quadro. Valeu.",
"1xaroqk": "{0}, {1} no ar. Se foi melhor que o padrão, envie os números com uma ou duas palavras para quem ajusta o simulador. Nada é enviado a menos que você aperte Enviar.",
"12j7air": "Foi melhor que o padrão?",
"1qjshkq": "{0}. {1} no ar com o {2}.",
"1k9f9e0": "Se foi, você pode enviar esses números com uma ou duas palavras para quem ajusta o simulador. Nada é enviado a menos que você aperte Enviar na próxima tela.",
"lmpjg0": "Melhor que o padrão",
