"bhqymg": "Parar de perguntar",
"159zlyr": "Valeu, é útil saber",
"1v1dzby": "Um ajuste que pareceu igual ou pior mostra a quem ajusta o simulador para onde não ir. Quer enviar este resultado também? Nada é enviado a menos que você diga.",
"1vcax0y": "Enviar este resultado",
"13gi980": "Enviar seu ajuste",
"pve1j9": "{0}. {1} no ar com o {2}. Isso vai para o quadro com as suas palavras, agrupado por aeronave e por versão da física, para que quem ajusta o simulador veja o que os pilotos preferem. Seu ajuste, seus rates e os mesmos detalhes de um relato de sensação de voo vão junto.",
