"seaqq": "O quadro não está respondendo, então os tempos dele não podem ser mostrados.",
"zc4ait": "Ainda não há tempo de três voltas nesta pista. A RaceGOW conta três voltas seguidas, e o primeiro é seu.",
"jax78i": "Ainda não há tempos publicados nesta pista. O primeiro é seu.",
"1xawzzq": "Peso {0}%",
"obojrp": "Prévia indisponível.",
"pfuxer": "Prévia do mundo",
"1889adu": "Pista da semana",
"96px0t": "{0}. {1} lidera com {2}. A melhor volta até segunda vence a semana.",
"z9xxt4": "{0}. Ninguém fez uma volta nela esta semana, então a primeira lidera.",
"9h1zsw": "Polegar esquerdo",
"l92ddx": "Polegar direito",
"11li9o0": "O canto inteiro",
"653lk2": "O pad é maior que o desenho: o stick fica onde seu polegar pousar no canto de baixo, e a deflexão é o arrasto a partir dali.",
"c7cdxu": "Paisagem",
"1cau3o4": "Vire o celular de lado. Os pads ficam sob os dois polegares, como um rádio nas duas mãos.",
"b46ibj": "Tartaruga",
"4uqxss": "Se você acabar de cabeça para baixo no chão, aparece o aviso TURTLE MODE. Dê arfagem ou rolagem no pad direito para desvirar. Não precisa acertar o tempo. Solte e decole.",
"1qyunph": "O botão de pausa, no canto superior direito. Batidas quicam. A punição é o tempo. Retome e dê arfagem ou rolagem se estiver de cabeça para baixo.",
"j3nmgx": "Voe pelo que pulsa. Verde é o lado de passagem, vermelho é a face errada.",
"lkidd0": "Stick esquerdo (Modo {0})",
"dgt1q3": "{0}. Defina o modo no rádio; esta página acompanha em Configurações.",
"1a3en5u": "Coloque o rádio no modo joystick antes de carregar esta página e depois rode Calibrar sticks em Configurações.",
"8pq8oh": "A arfagem move o cursor, rolagem para a direita seleciona, rolagem para a esquerda volta. Depois de uma pausa ou de uma chegada, espere um instante com os sticks parados e segure a rolagem por um momento.",
"d45qj0": "Reiniciar",
"ezjsbi": "R no teclado, ou uma chave no rádio: Configurações, Chave de reinício, e então acione.",
"o7cl2g": "Ao soltar, ele mantém a atitude em que você deixou. Toda curva precisa ser desfeita voando.",
"etorb5": "Se você acabar de cabeça para baixo no chão, aparece o aviso TURTLE MODE. Dê arfagem ou rolagem com o stick direito para desvirar. Não precisa acertar o tempo. Centralize o stick e decole.",
"1ri6cg": "O que é",
"14tfw5g": "Ligar",
"1eqzli7": "Quad, Controle de largada, Ligado. Fica desligado até você ligar. Depois pressione L na linha de largada, antes de subir o acelerador.",
"14cfpm3": "Definir o ângulo",
"11n5q78": "Acelerador em marcha lenta. Incline para frente até o OSD mostrar uns 30 a 40 graus. Centralize o stick. Os motores seguram.",
"1aa3oyb": "Dê a arrancada acima de uns 20 por cento. A trava solta, as hélices mordem e você está voando. L de novo reinicia depois de uma largada.",
"14arqvb": "Seta para cima é arfagem para frente. W é o acelerador. O controle de largada passa você para Acro durante a trava, e o seu modo volta depois que você sai.",
"r89zwp": "A mesma sequência de uma placa de verdade. L é a chave de modo. Ajuste launch_angle_limit e launch_trigger_throttle_percent na Bancada de firmware, dentro de Quad.",
"1wrrqt3": "Se você tombar na largada, o TURTLE MODE assume. Dê arfagem ou rolagem para desvirar. Não precisa acertar o tempo. Centralize o stick, pressione L e largue de novo.",
"1x7j2uc": "Controle de largada, se você ligou em Quad. Incline, centralize, arranque.",
"1xmpyfk": "Alterna entre Angle e Acro em voo e mantém a escolha.",
"1eyul69": "R, depois Escape",
"1ns2uml": "De volta à linha de largada, e pausa.",
"1hg0wdz": "Se você acabar de cabeça para baixo no chão, aparece o aviso TURTLE MODE. Dê arfagem ou rolagem com as setas para desvirar. Não precisa acertar o tempo. Solte e decole.",
"19jaz7h": "Relate um erro ou dê sua opinião. Pausa se você estiver no ar e depois abre o formulário.",
"1ogqofk": "Os pads aparecem em voo, sob seus polegares.",
"1harh8g": "Mexa os sticks. Estes acompanham o rádio.",
"149s8uu": "L arma. Incline, centralize, arranque. Os gimbals continuam seguindo suas mãos.",
"rt9bay": "Pressione as teclas. Estes acompanham suas mãos.",
"utog3i": "Os sticks de polegar são um stick proporcional de verdade, então voam no Modo de voo definido em Quad: Acro, como um rádio, por padrão. Angle é mais suave enquanto você aprende: solte o pad direito e o quad se nivela sozinho.",
"1uqyqut": "Um rádio voa em Acro por padrão: os sticks pedem uma taxa de rotação, e soltar pede nenhuma, o que mantém a atitude em que o quad estiver. Mude em Modo de voo dentro de Quad, ou com M em voo.",
"wtsp1v": "Desligado por padrão, porque uma arrancada a partir da trava é violenta e nem todo mundo quer isso. Ligue em Quad e depois L na plataforma. A leitura verde LAUNCH é o ângulo de arfagem. Ela pisca quando o acelerador está perto de disparar.",
"t0ww0i": "Teclas estão ligadas ou desligadas, então o tempo segurando é o analógico: um toque move o stick um pouco, segurar deixa em uma quantidade boa de voar, e segurar bastante vai até o máximo. Corridas no teclado começam em Angle, então soltar nivela o quad.",
"arpbtx": "O que voar",
"1k22ek3": "Sem portões, sem volta, dois minutos",
"j7omzh": "Sem portões, sem volta, sem relógio",
"1pcy84h": "Recorde da pista",
"1ihgoer": "Nenhuma volta registrada ainda",
"10gi4nt": "Nenhum recorde ainda",
"tkyf31": "Melhor volta, portão a portão",
"a6ppg": "Sua volta, portão a portão",
"r92sb6": "Uma volta limpa só, então é disso que ela foi feita. Voe outra e a faixa mostra onde ela perdeu tempo.",
