"1k5dzyz": "Rodada limpa",
"kkya0r": "Nada que o reconhecedor conseguisse nomear. Uma manobra é uma rotação completa em um eixo, ou uma volta ao redor de algo: um flip, um roll, um 360 de guinada, um powerloop sob um corrimão. Fazer uma curva não é manobra e, de propósito, não vale nada.",
"1y2kek1": "Dois minutos e nada que o reconhecedor conseguisse nomear. Uma manobra é uma rotação completa em um eixo, ou uma volta ao redor de algo: um flip, um roll, um 360 de guinada, um powerloop sob um corrimão. Fazer uma curva não é manobra e, de propósito, não vale nada.",
"m2e6mk": "Mais um tipo de manobra",
"1rjo3vh": "Publicar esta rodada envia ao quadro a pontuação de manobras, {0}. O quadro por enquanto só conhece manobras, então os vãos, os quase toques e a perseguição em {1} contam aqui e não lá.",
"1lipfcv": "O quadro só aceita manobras, e esta rodada não nomeou nenhuma, então não há nada para publicar. Os vãos, os quase toques e a perseguição em {0} contam aqui.",
