"18qtwr8": "Os sticks desenhados seguem sua calibração salva.",
"pjwruo": "Os sticks desenhados são como esta página lê agora, o que é um palpite até você calibrar. Se não seguirem suas mãos, escolha mesmo assim e rode Calibrar sticks em {0}.",
