"p9ydk8": "Sticks de polegar",
"1lrz4zo": "Um polegar no vidro tem cerca de um quarto do curso de um gimbal e nada que o centralize, então os números abaixo começam mais suaves que os padrões do rádio. Rolagem, arfagem e guinada voltam quando você solta; o acelerador fica onde você deixou, como em um rádio.",
"iulg1q": "Uma tecla não é um stick. Segurar uma leva o stick a 34 por cento e ele fica ali até cerca de três quartos de segundo, depois estica até o máximo em um segundo e um quarto. Então os rates abaixo são os que um RÁDIO voaria: um toque chega a mais ou menos um terço deles, e é por isso que o voo no teclado parece mais firme e mais lento para responder do que os números dizem. Um controle ou um rádio em modo joystick USB recebe a curva inteira. E uma corrida no teclado começa em Angle, que ignora esta curva: Corridas no teclado dentro de Quad, ou M em voo, mudam para Acro.",
"j83vdk": "Esperando o rádio responder. Mexa um stick.",
"pc5ckr": "Seu rádio está atualizando {0} vezes por segundo. O Betaflight voa em uma grade fixa de 250 Hz de qualquer jeito, então isto mostra o quanto o valor em cada um desses quadros é recente.",
"tn3t15": "Essa é a sua taxa de quadros, {0} por segundo, o que significa que este navegador só lê o rádio uma vez por quadro desenhado. O feedforward trabalha sobre a MUDANÇA entre quadros, então um stick que dá um passo por quadro é sentido como uma série de toquinhos em vez de um empurrão. Nada nos rates abaixo resolve isso.",
"1iahfwq": "Este rádio informa cerca de {0} passos no curso inteiro de um stick, grosso o bastante para se sentir em rates altos. Um rádio com relatório USB mais fino, ou rates mais baixos, suavizam isso.",
