"io45i2": "Três voltas com um portão de mergulho no canto distante e um portão duplo no caminho de volta.",
"8u176m": "Tudo do capítulo de portões em uma volta: mudanças de altura, um mergulho e um portão duplo, em ritmo de corrida.",
