"1vsz3ng": "Freestyle",
"1wiako2": "Hibari Yard, um mapa de freestyle inteiro: seus vãos com nome, as manobras voadas ao redor de objetos e uma rodada pontuada.",
"xqxbdn": "Ache seu caminho pelo pátio: por baixo da passarela na pista leste e por baixo do outdoor ao lado dos contêineres.",
"hki6u7": "Um mapa de freestyle não tem portões: os vãos estão onde você os encontra. Todo vão com nome conta no momento em que você passa por ele.",
"152zeb8": "O outdoor fica a leste das plataformas, depois dos contêineres.",
"1crudib": "A passarela cruza a pista no extremo leste.",
"q5ezlt": "Em qualquer ordem. O marcador aponta para o mais próximo que falta.",
"1eeae32": "Outdoor e passarela",
"1s35013": "Siga o marcador.",
"1r676n4": "Voe o pátio devagar uma vez. Os vãos são mais largos do que parecem de longe.",
"1cfgwhf": "Um Powerloop: por baixo de algo, para cima e por cima de costas em um loop completo, e saia por baixo pelo lado de onde entrou.",
"10z8axs": "O Powerloop é a manobra que todo piloto de freestyle aprende primeiro, porque é um flip que vai para algum lugar. Ele é julgado ao redor de um objeto, então precisa de um com ar embaixo.",
"n33ddu": "Voe em direção à passarela na pista leste, ou ao outdoor, baixo o bastante para passar por baixo.",
"hmlfmb": "Embaixo dele, puxe forte para trás com o acelerador para cima: suba pelo lado de lá e passe por cima.",
"kccig3": "Acelerador para baixo no topo, segure na descida e saia voando por baixo de novo.",
"7sufmz": "As manobras são nomeadas pelo jogo enquanto ele vê você voar. Se ele nomear outra coisa, o treinador vai dizer o que viu.",
"1knh4w4": "Acerte um Powerloop",
"zijhzx": "Por baixo primeiro, depois para cima e por cima.",
"lvkq4c": "Comece o loop mais longe do objeto, e puxe mais forte.",
"wshog": "Um Split-S: por cima de um objeto, meio roll até ficar de cabeça para baixo, depois puxe meio loop e saia por baixo, voltando pelo lado de onde veio.",
"1ol03po": "O Split-S vira você e desce em um movimento só. Sobre algo por baixo do qual dá para voltar, é uma manobra; em uma pista de corrida é como se faz uma curva fechada para baixo.",
"1jv2vfw": "Voe por cima do outdoor ou da passarela, com altura.",
"1em6sa5": "Meio roll até ficar de cabeça para baixo ao passar por cima.",
"dczjvg": "Puxe para trás em meio loop e saia voando por baixo.",
"d63ovn": "Acerte um Split-S",
"2diuts": "Por cima, meio roll, puxe até o fim.",
"1vhb4s7": "Mais altura acima do objeto antes de rolar.",
"ap4c04": "Um Matty Flip: voe por cima de um objeto, dê meio flip para frente e saia voando de volta por baixo dele.",
"lc3ht3": "O Matty Flip é o Powerloop ao contrário: por cima, depois de volta por baixo. O flip para frente no topo é o que faz parecer fácil.",
"u488c9": "Voe por cima do outdoor ou da passarela, devagar.",
"avhmds": "Empurre para frente para dar meio flip ao passar por cima.",
"1456hbj": "Acelerador para voar de volta por baixo, pelo lado de onde veio.",
"ujoh89": "Acerte um Matty Flip",
"63ds5i": "Por cima, flip para frente, de volta por baixo.",
"6ikkcv": "Mais devagar no topo. Um Matty Flip é voado em ritmo de caminhada.",
"1fsr9l8": "Lá no alto",
"f2lzzq": "Os dois vãos altos: entre as pernas da caixa d'água, e o vão do guindaste sobre o telhado do escritório, embaixo da lança.",
"15d394s": "Vãos altos são voados sem nada embaixo de você além de ar. A linha é a mesma lá de baixo; a coragem não.",
"11xywr3": "Suba até a altura do vão bem antes de chegar.",
"xvjpxm": "Alinhe de longe, como em qualquer vão.",
"hwpfle": "Passe e vá embora. Não olhe para baixo.",
"1wzvmop": "Caixa d'água e vão do guindaste",
"1gzin5e": "Suba primeiro, depois alinhe.",
"m2u227": "Suba até a altura primeiro e desacelere. O vão da caixa d'água é estreito.",
"abjcx4": "Rodada de pontos",
"1pimbly": "Noventa segundos, voados por pontos: vãos, quase toques e manobras, ligados em combos. Feche pelo menos 1.500.",
"1eai7a9": "Uma rodada de freestyle é julgada pelo que você liga. Um movimento depois do outro, sem intervalo, multiplica todos eles.",
"110emqo": "Planeje uma linha por dois ou três vãos próximos.",
"7v674o": "Encaixe uma manobra entre eles e passe raspando nas paredes.",
"1sxec9f": "Continue em movimento: um combo é fechado quando termina.",
"1goxdcb": "Feche 1.500 pontos em 90 s",
"1mrs32o": "Ligue movimentos em combos.",
"16jbbnf": "Ligue suas linhas: um vão, uma manobra e um quase toque em um combo só valem mais que os três separados.",
"6rc0y3": "Uma batida perde o combo que você estava montando. Voe dentro do seu limite.",
"ldrdy3": "Licença Pro",
"tmqbwn": "Quatro finais que juntam tudo. Passe em todas e você é piloto.",
"1s17205": "Voo de avaliação",
"16hzql1": "A avaliação completa: os anéis altos e baixos, um flip, um roll, um voo de faca e um pouso na plataforma. Uma batida encerra tudo.",
"1ww9mzx": "Um voo de avaliação são as habilidades que você já tem, voadas uma após a outra, com um pouco de pressão. Cada uma é uma lição em que você já passou.",
"orqnox": "Primeiro os anéis, altos e baixos, em ordem.",
"1eum8p9": "Depois um flip e um roll, para qualquer lado, com altura.",
"2cw9on": "Um segundo de voo de faca, depois volte à plataforma e desça com calma.",
"p7p43g": "Sem batidas. Se você bater, o voo de avaliação começa de novo.",
