"dyq2u1": "Um voo de avaliação se voa dentro do seu limite. Mais devagar, e termine.",
"1et3yvj": "Final de vãos",
"1b0ofao": "Todos os vãos da Escola de vãos em ordem, o mais rápido que puder, e depois pouse na plataforma.",
"8pg9yc": "A linha de vãos do capítulo quatro, voada contra um relógio apertado e terminada direito: na plataforma, não em um monte.",
"izg60j": "Largo, sob a ponte, seis e quatro.",
"1oxd7uv": "Contorne até o outdoor, cruze até a galeria.",
"1v35rud": "Volte para a plataforma e pouse.",
"1xk7pnh": "Volte para a plataforma.",
"ncqy5t": "A linha é a mesma do capítulo quatro. Voe uma vez nesse ritmo e depois force.",
"117844s": "Final de freestyle",
"14s5p1n": "Em uma rodada só: um Powerloop, um Split-S e o túnel de contêineres.",
"1rq5gs6": "Freestyle é manobras e linhas em um voo só. O túnel de contêineres é o vão mais apertado do pátio.",
"xjg1n7": "Um Powerloop em volta da passarela ou do outdoor: por baixo, para cima e por cima.",
"1vhfmbp": "Um Split-S sobre o outdoor ou a passarela.",
"18rmrzm": "Depois alinhe de longe e voe o túnel de contêineres.",
"eopxfn": "O túnel de contêineres",
"duwceq": "TÚNEL DE CONTÊINERES",
"137u7rb": "Alinhe bem de trás.",
"nvuhsa": "O túnel é estreito. Devagar e reto ganha de rápido e de lado.",
"s84ra4": "Campeonato",
"1teciwh": "Cinco voltas no Grand Prix. A última lição da carreira.",
"1rke9r2": "Um campeonato é vencido pelo piloto que ainda é rápido na última volta. Cinco voltas bastam para descobrir.",
"nlbnxy": "Uma primeira volta limpa. Nada se ganha nela, e muito pode ser perdido.",
"1wfto5c": "Chegue ao seu ritmo nas duas seguintes.",
"1ps4rq0": "Segure nas duas últimas. Aí você está licenciado.",
