"1bwubn9": "Cinco voltas é muito tempo. Guarde um pouco de folga.",
"1yui2tl": "Licença Novato",
"cglr1y": "Um voo de avaliação com tudo o que Aprenda a voar ensinou, em Acro. Passe e os dois caminhos se abrem: corrida e freestyle.",
"jeps4t": "Seu primeiro voo de avaliação: o circuito de anéis em Acro, um círculo em volta da torre e um pouso suave na plataforma. Uma batida encerra tudo.",
"iz4xrq": "Tudo desde o seu primeiro pairado, voado de uma vez. Uma licença não é uma rodada rápida, é uma limpa: os mesmos comandos suaves do primeiro anel até a plataforma.",
"gx2g4y": "Decole e voe o circuito de anéis, em ordem, a uma altura constante.",
"17u3dsc": "Depois um círculo em volta da torre, inclinado e mantido com um leve puxão.",
"jiuobt": "De volta à plataforma, reduza bem e pouse com calma.",
"11vj5l5": "Sem batidas. Se você bater, o voo de avaliação começa de novo. Vá com calma: uma rodada limpa ganha de uma rápida.",
"1en967s": "O circuito de anéis",
"wq9fv8": "O anel aceso é o próximo. Alinhe cedo.",
"1ikj53a": "Um círculo em volta da torre",
"1b5lfu9": "Rolagem e guinada juntas, e puxe um pouco para manter a curva.",
"hex4y3": "Reduza bem antes da plataforma e depois baixe o acelerador aos poucos.",
"17vb0z3": "Uma licença se voa dentro do seu limite. Mais devagar, mais suave, e termine.",
"rwfpwa": "Arte da corrida",
"11lx0nq": "O que vence corridas entre os portões: a largada, a frenagem, a linha, bater a sua própria volta e a mesma volta cinco vezes.",
