"7a2j43": "Corridas são ganhas e perdidas nos três primeiros portões, antes que alguém possa ultrapassar. Acelerador no máximo saindo das plataformas, com o nariz já apontado para o primeiro portão.",
"1y6qq90": "Dê tudo no {throttle} no instante em que a rodada começar, com um pouco de {pitch} para a frente.",
"1s9569": "Nivele na altura do portão antes do primeiro portão, não depois.",
"1del7ab": "Leve a velocidade até o terceiro portão. Sem batida, sem segunda chance.",
