"tanpzj": "Velocidade na reta é desperdiçada se você passar da curva. Freie tarde e forte, vire e depois acelere na saída: os pilotos mais rápidos são os melhores em desacelerar.",
"2wx86i": "Pela reta com o acelerador aberto: os anéis rápidos pedem pelo menos 47 km/h.",
"oteta6": "No anel de frenagem, incline para trás com {pitch} para ficar abaixo de 32 km/h.",
"1w4vt5f": "Contorne a bandeira e depois acelere pela próxima reta.",
"i18lue": "Um anel voado rápido demais ou devagar demais não conta, e fica aceso até você voar certo.",
"12o42tv": "Rápido, freie, vire, duas vezes",
"l69f1h": "Rápido na reta, devagar ao entrar na curva.",
"1n56sh1": "Freie mais cedo. Uma curva feita devagar é mais rápida que uma curva feita na grama.",
"sxv63q": "A linha",
