"1vf4i9f": "A linha de corrida é decidida antes do portão, não nele. Cada anel fica logo antes do seu portão, de frente para ele: passe pelo anel e o portão fica fácil.",
"5c9q7g": "Olhe para o anel, não para o portão atrás dele.",
"1xb5d60": "Vire cedo para sair da curva já de frente.",
