"1sogvgp": "Um whoop é um quad de corrida para a sala de estar. É leve, quica nas paredes e seus portões são minúsculos, então é tudo controle de acelerador e pequenos movimentos de stick.",
"1bf4qew": "Movimentos pequenos: um whoop vira rápido, então entre com calma em cada curva.",
"1fl8jsh": "Fique baixo. Os portões estão na altura dos seus joelhos, não da cabeça.",
"173ox8n": "Três voltas. Encostou em um portão, continue: um whoop perdoa.",
