"u2vz18": "Portas francesas, pavilhão, janela da cozinha",
"joggwc": "PORTAS FRANCESAS",
"dhgged": "JANELA DA COZINHA",
"1lar6h5": "Nessa ordem. Alinhe de longe.",
"1ohrtue": "A janela da cozinha é menor do que parece. Reduza e alinhe de frente para ela.",
"52cuq5": "Linha das árvores",
"1qn5ynq": "A linha da corrida ao longo do bosque de Joshua Bardwell: o canto norte, por cima da cerca, o alto do bosque, para dentro das árvores e o portão oeste. Depois passe entre duas árvores duas vezes.",
"1c8lvhq": "Árvores são a proximidade mais difícil que existe: finas, por toda parte, e não saem da frente. Voar uma linha entre elas é o que faz um piloto de freestyle.",
"hycnfh": "Para leste, do gramado até a moldura do canto norte, depois por cima da cerca.",
"u36qq": "Para oeste pelo alto do bosque e para dentro das árvores.",
"b7q0e2": "Saia pelo portão oeste, depois ache duas árvores próximas e voe entre elas.",
"1qpmntj": "Ao longo do bosque",
"oqgbds": "O CANTO NORTE",
"1cfykd9": "POR CIMA DA CERCA",
"s23tod": "O ALTO DO BOSQUE",
"wmb22h": "PARA DENTRO DAS ÁRVORES",
"1vztdvi": "O PORTÃO OESTE",
"176lt2": "Siga o marcador, de moldura em moldura.",
"189date": "Passe entre duas árvores, duas vezes",
"14wwswk": "Entre dois troncos, nivelado.",
"2026ps": "Olhe para o vão entre as árvores, nunca para uma árvore.",
"byize": "Por baixo de tudo",
"58ixa4": "Voe por baixo de quatro coisas na cidade: uma ponte, um passadiço, uma sacada, um guindaste. Qualquer coisa com ar embaixo.",
"lgmoi3": "Passar por baixo é o movimento de proximidade que fica mais bonito em vídeo: o mundo cai sobre a câmera e some. É um vão sem laterais, então é tudo controle de altura.",
"yekjzq": "Ache algo com um vão embaixo: a passagem de nível, uma passarela, um passadiço.",
"1ti7zmq": "Desça cedo até a altura e passe por baixo nivelado.",
"8d6v41": "Quatro, em qualquer lugar da cidade.",
"141so3r": "A cidade é grande: a primeira fica a um voo curto da largada.",
"1f7npj4": "Por baixo de quatro coisas",
"1ef4yjq": "Desça cedo, passe por baixo nivelado.",
"yyd0pk": "Chegue à altura antes da coisa, não embaixo dela.",
"krou27": "O quintal de Heads",
"jb7ldm": "Em volta da casa de Heads, de Infinity Loops: saia pelo portão lateral, volte pelo portão da garagem e some 600 pontos de quase toques pelo caminho.",
"4uyffh": "Heads voa este quintal perto de tudo. Uma rodada de proximidade é uma linha que mantém você junto de paredes, cercas e sob os beirais a volta inteira.",
"99cko": "Saia da garagem e faça um rasante ao longo da casa até o portão lateral.",
"1bazhed": "Contorne pelos fundos, baixo ao longo das cercas.",
"1oq26iu": "Entre pelo portão da garagem. Rasantes, passagens entre e passagens por baixo, tudo conta.",
"snrm28": "A casa de Heads, voada com um whoop.",
"1cgdslc": "Portão lateral e portão da garagem",
"p20s5x": "PORTÃO LATERAL",
"1w7ypdw": "O PORTÃO DA GARAGEM",
"50pbtt": "Ao longo das paredes e cercas.",
"m4lho9": "Quase toques só pagam quando você sai ileso. Alivie até conseguir.",
"12bghr0": "Linhas",
"gby171": "Freestyle é uma linha: movimentos ligados sem intervalo entre eles. Combos em Hibari Yard, depois rodadas suas em Infinity Loops e Baka.",
"19bdsiz": "Primeiro combo",
"167qo1q": "Um combo de três movimentos: vãos, manobras ou quase toques, um logo depois do outro, fechado limpo.",
"17990ho": "Um combo são movimentos ligados com poucos segundos entre si. Cada um o mantém aberto, e ele é fechado quando você para. Ligados, pagam muito mais que os mesmos movimentos separados.",
"qx6r6k": "Por um vão, e direto para um rasante ao longo de um contêiner.",
"1gvqto0": "Depois um flip ou um roll antes de o combo fechar.",
"1ttc7y": "Continue voando limpo: uma batida perde o combo inteiro.",
"1q9glzs": "A barra de combo à direita mostra quanto tempo você tem para ligar o próximo movimento.",
"13strv": "Um combo de três",
"zct0ou": "De um movimento direto para o próximo.",
"1gsqrry": "Uma batida perde o combo. Ligue primeiro movimentos fáceis.",
"7cukoz": "Do vão à manobra",
"1xwe34z": "Um combo com um vão nomeado e uma manobra, ligados: pelo vão e direto para um flip, um roll ou um Powerloop.",
"f6tckd": "Do vão à manobra é a linha de freestyle em uma frase. A manobra precisa ser planejada antes do vão, porque depois não há tempo para pensar.",
"3gbvxn": "Escolha um vão com ar livre depois dele: o outdoor ou a passarela.",
"1864tje": "Passe por ele e vá direto para a sua manobra.",
"1b4elaf": "Complete e siga voando limpo para fechar o combo.",
"g6h1uw": "Um vão e uma manobra, ligados",
"zolhgc": "Pelo vão, depois a manobra.",
"lshhpa": "Suba depois do vão e antes da manobra. Altura é o que deixa uma manobra terminar.",
"r7bmb7": "Noventa segundos no mapa Infinity Loops do quadro, voados por pontos. Feche pelo menos 2.000.",
"pmn0bp": "Uma rodada de freestyle no mapa de outra pessoa é achar as linhas que o criador escondeu. O 90%er Gap é o que mais paga, se você conseguir achar.",
"1tn9e8b": "Dê uma volta para ver o que há.",
"mob5uv": "Ache duas ou três coisas próximas e ligue.",
"ye4weg": "Feche o combo antes de bater.",
"cwy0ng": "Do quadro, por Infinity Loops.",
"12bujxp": "Feche 2.000 pontos em 90 s",
"1j3tc2e": "Ache as linhas: dois vãos e uma manobra em um combo só pagam mais que os três separados.",
"f8era": "Uma batida perde o combo que você estava montando. Feche, depois vá de novo.",
"y0typ6": "Noventa segundos em volta da casa de Heads, de Infinity Loops, voados por pontos. Feche pelo menos 2.000.",
"1ncd29p": "A própria casa de Heads: portas, janelas, o porão e o quintal. Uma rodada de freestyle aqui é uma linha que passa por tudo isso.",
"u40a5q": "Ligue uma porta, uma janela e um rasante em um combo só.",
"5rysj6": "Dois minutos em Baka, o mapa de AuraNesian do quadro. Sua própria linha, voada por pontos. Feche pelo menos 3.000.",
"o8dp1u": "A última lição antes da Licença de Freestyle é a que não tem instruções: um mapa grande, dois minutos e a linha que você achar.",
"1jpgn9s": "Pontes, caixas d'água, prédios abandonados e árvores: planeje uma linha por eles.",
"1a6lzah": "Ligue vãos, quase toques e manobras em combos longos.",
"1mtdhjl": "Feche com frequência. Dois minutos é tempo de sobra para uma batida.",
"1mvv2ua": "Do quadro, por AuraNesian.",
"1hf8p8y": "Feche 3.000 pontos em 2 min",
"1d5y9oa": "Sua própria linha.",
"1o9vwu4": "Combos mais longos pagam mais que mais combos: de um movimento direto para o próximo.",
"1rndnup": "Feche o combo antes do movimento arriscado, não depois.",
"xjgvd8": "Dois minutos em Hibari Yard, sua própria linha, voada por pontos. Feche pelo menos 3.000.",
"unp3gj": "Não foi possível acessar o quadro, então esta rodada é em Hibari Yard: a última lição antes da Licença de Freestyle, sem instruções.",
