"1gh8gk1": "Você é a câmera. Filme as batalhas de drift por um minuto.",
"exsh29": "Voe baixo para levar as cabras até a garagem do Heads. O relógio começa na primeira cabra que você mover.",
"fk6a7t": "Sem relógio e sem portões. Voe a escola inteira.",
"s8ff1t": "Dois minutos. O relógio começa na primeira coisa que você pontuar.",
"10qifom": "Sem relógio e sem portões.",
