"cyw1pe": "Um simulador de corrida FPV no navegador. A controladora é Betaflight. A linguagem de pistas vem do Track Draw. O resto é um piloto e as pessoas que voaram até ficar certo.",
"1sncokl": "Feito por",
"kai17": "Construiu este simulador, o editor e o quadro público. Regeu uma horda de Grok e Claude pelo caminho.",
"1rju5ni": "Parceiros",
"10ax242": "Eles apoiam o WebFPV.",
"1fpu7yw": "Pilotos de teste beta",
"2sef6d": "Eles voaram até parecer um quad.",
"lq4qk4": "A controladora",
"152d3mr": "Os rates, o loop PID, os filtros, feedforward, TPA, iterm relax, airmode, anti-gravity. Compilados nesta página, não reescritos.",
"kfh8vm": "é GPLv3, então isto também é. A tela da controladora de voo é uma homenagem ao",
"1ol0nlq": "10.10: nomes das abas, campos da 4.5.1, e o clássico cinza escuro com laranja. Não é aquele aplicativo. Sem Vue, sem MSP, sem iframe. Com agradecimentos aos desenvolvedores do Betaflight.",
"kwollz": "A linguagem de pistas",
"91xq6y": "O editor é inspirado no",
"1v1kv66": ", dos deuses holandeses dos drones do",
"1ffizjn": "As salas RaceGOW5",
"ov7ihs": "Oito pistas, seis construtores, lidas das animações oficiais.",
"f0ewtp": "Série e animações de",
"432t9y": "A horda",
"gw6sa5": "Escrito com Grok. Construído com Claude.",
"1m26mn1": "Grok, da xAI. Muitas das linhas, muitas das discussões e muita da teimosia sobre a sensação de voo.",
"1i8y2kj": "Claude, da Anthropic. A outra metade da horda. O mesmo humano segurando os sticks.",
"sskqzq": "Betaflight, Track Draw, Grok, Claude, Dutch Drone Squad e suas marcas pertencem a seus donos. As imagens dos canais pertencem aos pilotos. Usá-las aqui é crédito, não uma alegação de que endossam esta página. As marcas dos parceiros pertencem aos parceiros, exibidas com o acordo deles. WebFPV é software livre sob",
