"1iamjsl": "{0} tem {1} {2} aqui, muito pouco para voar. No EdgeTX, coloque o modo joystick USB em Classic e conecte de novo.",
"1m0xh9s": "Seu joystick",
"1iyz2p7": "Nenhum rádio ou controle encontrado. Conecte um, coloque em modo joystick e recarregue.",
"awvaaq": "Nenhum rádio ou controle encontrado. Conecte um, coloque em modo joystick e depois mexa nele.",
"1bcu86u": "{0}{1} está conectado, mas este navegador o mostra com {2} {3}, e voar precisa de quatro. Em um rádio EdgeTX, coloque o modo joystick USB do modelo em Classic, depois desconecte o rádio e conecte de novo.",
"r0fr7u": "Um joystick",
"1k67jhh": "{0} não está chegando ao simulador. Pause para abrir a ajuda dos sticks.",
"1g3lqvf": "Nenhum rádio ou controle está chegando a este navegador ainda. Conecte, coloque em modo joystick e mexa um stick: um navegador só mostra um controle a uma página quando algo nele se move.",
"l55p9d": "Sua calibração salva lê {0} de um eixo que este controle não tem, então {1} nada. Ele tem {2}. Calibrar sticks mapeia de novo a partir do que ele realmente envia.",
"10cte0": "O eixo {0} está se movendo como um stick, e nada no simulador o lê. O navegador tem o seu stick; o simulador o tem no canal errado. Calibrar sticks resolve isso em cerca de um minuto.",
"13f86ul": "O eixo {0} está se movendo, e nada no simulador o lê. Se esse é o stick que não funciona, Calibrar sticks o coloca no canal certo.",
"3hxjne": "Isso é {0}, no eixo {1}, e está chegando ao simulador.",
"4pid3q": "{0} se moveu como um stick, e nada no simulador lê {1}. É um stick no canal errado, e Calibrar sticks resolve.",
"13inlwb": "Mova o stick que não funciona até o fim em cada ponta e observe as barras.",
"2niqw0": "No rádio: escolha o modo joystick USB ao conectar, antes de abrir esta página, e confira o modelo selecionado nele. O modelo decide o que cada canal envia, e um novo ou vazio pode não enviar nada em um stick.",
"jem3gg": "Seu rádio está chegando como {0} eixos.",
"rr1z7d": "Se nenhuma barra se move: Windows",
"1j91r00": "Veja se o Windows enxerga o stick: aperte Windows e R, digite joy.cpl, aperte Enter, escolha seu rádio e abra Propriedades, depois mexa nele. Se ele se move lá e não aqui, relate um bug por esta tela e diga isso.",
"1qj9g8y": "Se ele também não se move lá, o rádio não está enviando. Calibrar naquela janela do Windows não muda nada do que um navegador lê, então não é preciso.",
"1elsn67": "Se nenhuma barra se move: Mac",
"193sfmd": "O macOS não tem um teste de sticks próprio, então estas barras são o teste. Se um stick se move aqui em um navegador e não em outro, relate um bug por esta tela e diga qual.",
"1lg87ci": "Se nenhuma barra se move: Linux",
"fk484m": "jstest-gtk ou evtest mostram o que o rádio está enviando. Se o stick se move lá e não aqui, relate um bug por esta tela e diga isso.",
"1ftvq9i": "Se nenhuma barra se move",
