"9s1w1d": "De uma a cinco estrelas, uma avaliação para cada um. Você pode mudar ou retirar. Os pilotos veem a média ao lado do nome, e o quadro pode colocar os melhores primeiro.",
"fi2r1e": "Compartilhar este ajuste",
