"1yprcf0": "Nada foi aberto: \"{0}\" tem mudanças que a pista que está chegando não tem, e elas não puderam ser guardadas, porque o armazenamento local está indisponível ou cheio. Exporte primeiro.",
"1o9kt4z": "\"{0}\" continua na tela: não pôde ser guardado em Carregar, porque o armazenamento local está indisponível ou cheio, então nada novo foi iniciado. Exporte antes em Mais e depois aperte Novo.",
