"14bxhiv": "Uma volta da linha de corrida, em loop, voada no mesmo ritmo em qualquer pista, então uma volta mais longa é um clipe mais longo. Esta aba precisa ficar aberta enquanto renderiza, e fechar esta caixa interrompe.",
