"p29khn": "Um zip com esta pista como arquivo que um programa consegue ler, uma página para montá-la, um mapa, vistas da sala com e sem a linha de corrida, e uma volta como animação. Esta aba precisa ficar aberta enquanto ele é feito, e fechar esta caixa interrompe.",
