"89yb7x": "Até cinco logos de patrocinadores, pintados sobre {0} onde você colocar: aperte \"Pintar sobre {1}\" embaixo de um e depois clique sobre {2}. Eles viajam dentro do arquivo do mapa, então um mapa que você envia para alguém chega com a marca aplicada.",
"11oynza": "Até cinco logos de patrocinadores. Eles são distribuídos pelos portões na ordem de voo, então cada patrocinador recebe uma parte das placas, das faixas verticais e das bandeiras, espalhada pela volta em vez de amontoada na largada. Qualquer um deles também pode ser pintado sobre {0}: aperte \"Pintar sobre {1}\" embaixo dele e depois clique sobre {2}. Eles viajam dentro do arquivo da pista, então uma pista que você envia para alguém chega com a marca aplicada.",
