"507afi": "Para frente contorna na ordem em que a estrada foi traçada, Ré no sentido contrário.",
"qs5x7t": "Este veículo não tem estrada, então fica estacionado na fila ao longo da borda sul do terreno. Arraste-o para uma estrada.",
