"z7pdd0": "Espaçamento dos níveis",
"120dj14": "{0} é a subida de uma abertura até a próxima, de borda inferior a borda inferior. Duas aberturas compartilham um tubo da moldura, então o espaçamento natural é a altura da abertura mais o tubo, que é o que um preset define.",
