"zoltl8": "{0} Topo da estrutura a {1}{2}.",
"1cy6t48": "Cada abertura",
"4ikah4": "Cada abertura de uma pilha é um portão próprio: dê a ela largura e altura próprias, e a corrida pontua cada passagem pelo tamanho daquela abertura. Uma abertura em que você não mexe fica com o tamanho da pilha, acima.",
