"1ugsv61": "Largura da letra",
"1s7eddk": "Altura da letra",
"vq42m7": "{0}. O tubo é de 2 polegadas, e o tubo de uma letra é sólido.",
"18ku1py": "Transformar em portão",
"h5sgwm": "Um portão comum onde fica o vão principal, do mesmo tamanho dele. A passagem por qualquer outro vão sai da ordem.",
"q7q9fq": "Moldura",
"r64mng": "O tubo é retirado: os vãos ainda pontuam e acendem, e não há nada em que bater. Na sala ela aparece só como os vãos.",
"s9vozj": "A letra é feita de tubo. Deixe-a invisível para manter os vãos como alvos sem nada construído em volta.",
"1rkao2q": "Colocar o tubo de volta",
"1ezapez": "Deixar invisível",
"1h88uzq": "Cada lado é um tubo próprio: a barra de cima fica sobre a abertura de cima e a barra de baixo sob a mais baixa, e um poste é um trecho por abertura. Os botões Esquerda e Direita tiram o poste inteiro; os botões abaixo deles tiram o trecho de uma abertura. Tire um e as aberturas ainda pontuam. Na vista 3D, clique em um tubo do portão selecionado e aperte Delete: isso tira só o trecho em que você clicou. Esquerda e direita são como vistas de frente para o portão, como a bandeira da travessa.",
"3wzvo0": "Cada lado é um tubo próprio. Tire um e a abertura ainda pontua e acende, sem tubo ali para bater. Na vista 3D, clique em um tubo do portão selecionado e aperte Delete. Esquerda e direita são como vistas de frente para o portão, como a bandeira da travessa.",
