"a9ak0k": "Tirar o trecho: {0}",
"1mtqtr1": "Colocar de volta o trecho: {0}",
"1302s3v": "Colocar a moldura de volta",
"ka4wbv": "Colocar todos os lados de volta",
"103wg51": "Tira todos os lados, e a bandeira se houver: a abertura ainda pontua e acende, sem nada em que bater.",
"e2847m": "Bandeira da travessa",
"127gict": "Onde as flâmulas ficam em uma barreira: nas pontas. A altura do mastro é a altura da bandeira nas dimensões abaixo, e o mastro é sólido.",
"17wx66j": "Onde a flâmula fica na travessa, vista de frente para o portão. Em cima coloca um mastro no meio da placa, bem acima da abertura. A altura do mastro é a altura da bandeira nas dimensões abaixo, e o mastro é sólido: um piloto mergulhando sobre a barra de cima pode bater nele.",
"d0y2y3": "Vão",
"1w31kfz": "O quadrado verde é o espaço pelo qual você precisa passar voando. Arraste a alça redonda na planta para girá-lo para qualquer ponto em volta do marcador, a volta inteira. Inverter lado manda o quadrado para o lado oposto, e Recalcular o devolve à regra automática, que é o lado de fora da curva.",
"1wg2ncb": "Inverter face",
"172xku9": "Inverter lado",
"3d7qa3": "Atalho: X",
"1tdvisw": "Recalcular",
"qqpglk": "Devolve isto à regra automática, que o aponta ao longo da linha do elemento anterior até o próximo.",
"1c086it": "Nada selecionado. Clique em um elemento para editá-lo, ou arraste uma caixa no chão vazio para selecionar vários.",
"3eggiu": ": RaceGOW, para um whoop de 65 mm em uma sala. Portões de 24 a 28 in, portões adjacentes a 30 in de centro a centro, e a pista inteira dentro de 4 por 6 ft no menor portão, ampliada junto com eles. Cada peça é medida em polegadas a partir do meio da sala, e a grade é de uma polegada.",
"1329h41": ": um quad de cinco polegadas em um campo. Tamanhos de portão da MultiGP, e cada peça medida em metros a partir do canto do campo.",
