"a17t5z": "Recomeçar",
"92kvsy": "Esvaziar a ordem de voo e começar de novo, incluindo os pontos de passagem. Um desfazer traz de volta",
"1cfa0q1": "Uma página para imprimir: onde fica cada peça, medido a partir de um canto, e que tubos e conexões comprar",
