"1l4fpy8": "Uma barreira é voada por cima.",
"5ozvlp": "Ordem de voo: toque na próxima peça. Uma peça de novo é mais uma passagem.{0} Toque no mais de novo para guardar a ferramenta.",
"1fj7bqd": "Ordem de voo: clique na próxima peça. Uma peça de novo é mais uma passagem.{0} Backspace tira a última passagem. Esc guarda a ferramenta.",
"16bob4g": "Ordem de voo: clique na primeira peça por onde a volta passa, depois na próxima. Uma peça de novo é mais uma passagem.{0} Esc guarda a ferramenta.",
"1h3i156": "Toque no piso para colocar um cubo: cinco portões em uma peça só, voados reto na direção para onde ele aponta. A ferramenta fica armada. Toque em Cubo de novo para guardar.",
"jihh0f": "Clique no piso para colocar um cubo: cinco portões em uma peça só, voados reto na direção para onde ele aponta. A ferramenta fica armada. Clique direito ou Esc guarda a ferramenta.",
"1hjaiqs": "Guarde em Ferramentas.",
"947ub9": "Toque nela de novo, à esquerda, para guardar.",
"ret7py": "Arraste pelo piso para colocar uma fila de dois ou três portões, a 30 in um do outro. Um clique coloca um par. Clique direito ou Esc guarda a ferramenta.",
"p956s2": "Clique em dois pontos para medir entre eles. Um clique perto de um portão ou de uma vara pega o meio dele. Clique direito ou Esc guarda a régua.",
"6y6p5i": "Clique em dois pontos para medir entre eles, em metros. Um clique perto de uma peça pega o meio dela. Clique direito ou Esc guarda a régua.",
"na57ja": "Arraste pelo chão, a partir do vão que é voado primeiro, para colocar um muro. Um toque coloca três. Um muro, e a ferramenta é guardada.",
"1x41sn8": "Arraste pelo chão, a partir do vão que é voado primeiro, para colocar um muro de portões que compartilham os postes, de dois a seis. Um clique coloca três. Um muro, e a ferramenta é guardada. Alt gira livremente.",
"3qzdj6": "Toque",
"m8sun": "Clique",
"lzc7fh": "Os formatos ficam em Ferramentas.",
"ybq1cu": "{0} onde vai o portão de lançamento: um portão horizontal a 15 ft de altura, atravessado para cima vindo de baixo, com a puxada e o empurrão por cima que o voam colocados como pontos de passagem. Um portão, e a ferramenta é guardada.",
"36gz3q": "{0} onde vai a barreira de barra: uma barra de 10 ft de largura a 5 ft de altura sobre duas pernas, atravessada na pista, com a volta passando por cima dela. O cartão diz por baixo ou rasante. Uma barreira, e a ferramenta é guardada.",
"1onrj1y": "{0} onde vai a barreira: uma placa de 4 m de comprimento e 1 m de altura com uma bandeira em cada ponta, atravessada na pista, com a volta passando por cima dela. Uma barreira, e a ferramenta é guardada.",
"1cwij39": "{0} onde vai o portão de subida: inclinado a 45 graus com a borda inferior a 1,5 m de altura, atravessado de baixo para cima. Um portão, e a ferramenta é guardada.",
"18zqy2o": "Clique sobre {0} para posicionar. A ferramenta fica armada, então um segundo clique coloca outro. Clique direito ou Esc guarda a ferramenta.",
