"1weh0ir": "Escolha uma ferramenta à esquerda para colocar mais.",
"dmd4gm": "Clique em um portão para selecioná-lo. Arraste sobre {0}, em um ponto vazio, para olhar em volta. Escolha uma ferramenta à esquerda para colocar mais.",
"13ytpyk": "Clique direito ou Esc guarda a ferramenta.",
"1sj82o4": "Clique direito ou Esc guarda a régua.",
"gy64hi": "Um carro anda em uma estrada, e este mapa ainda não tem nenhuma. Coloque uma com a ferramenta Estrada primeiro.",
"1wq4lkk": "Clique em uma peça para selecioná-la. Arraste para mover, e o anel no pé dela gira. Arraste o chão vazio para olhar em volta. Escolha uma ferramenta à esquerda para colocar mais.",
