"hmu6f5": "{0} não tem tamanho para o próprio tubo: o vão por onde se voa fica sem espaço nenhum depois que o tubo o contorna, então nada pode pontuar ali. Aumente a letra.",
"1xhn5ud": "{0} tem um vão de só {1} m no ponto mais largo, contra 1,5 m de um portão padrão, então um quad tem pouco espaço para atravessá-lo. Se a pista quer isso mesmo, ignore este aviso; se não, aumente a letra.",
"amkahr": "{0}. {1} não tem face de entrada definida, então a linha adivinhou uma.",
"1f6an1h": "{0} está fora do campo.",
"up72l1": "{0} e {1} estão no mesmo lugar, então a linha não tem direção entre eles.",
"1fgg8vv": "{0} aponta para longe de {1}. A linha sai ao contrário. Aperte X para inverter a face.",
"19psiq7": "{0} aponta de volta para {1}. A linha chega ao contrário. Aperte X para inverter a face.",
"1xkwf83": "A volta parte para longe de {0}. Gire as plataformas de largada, ou reordene a pista.",
"1vv4mnm": "A volta retorna a {0} vindo pela frente, depois de {1}. Inverta essa face, ou mova o último elemento para o lado de trás.",
"1gf0z7v": "Um quad em velocidade de corrida não voa isso. Se a pista quer isso mesmo, diminua Avisar abaixo do raio nas configurações do campo.",
"1bw4o5i": "Nada voa isso.",
"rz1y7k": "A linha atravessa {0} a {1} m ao longo da volta.",
"qlb5lu": "A linha sai do campo a {0} m ao longo da volta.",
"trp2du": "A linha vai para baixo do chão a {0} m ao longo da volta.",
"63njfk": "{0} e {1} ficam a {2} m um do outro, um depois do outro na ordem de voo, então uma passagem pode alcançar os dois. A corrida só conta {3} depois de mais {4} m de voo. Se a ideia é uma volta entre eles, afaste um.",
"1l1fncv": "{0} termina apontando para longe de {1}, então a linha precisa voltar sobre si mesma para chegar lá. Coloque {2} onde a figura termina, ou vire a figura para o outro lado.",
"1ozh84i": "{0} sai ao contrário para dentro de {1}, então a linha precisa voltar sobre si mesma para começar a figura. Vire {2} para o outro lado, ou mova a figura.",
"1emgxmg": "{0} começa voltando em direção a {1}, então a linha precisa voltar sobre si mesma para começar a figura. Coloque {2} onde a figura começa, ou vire a figura para o outro lado.",
"laqehz": "A linha passa por cima de {0} a {1} m ao longo da volta. A linha de uma bandeira sobe para sempre, então ela é contornada e nunca sobrevoada: mova a linha para um dos lados dela.",
"1xr491b": "{0} está {1} graus fora do esquadro em relação a {2}. Todo portão aponta ao longo de um dos dois eixos da pista: gire-o até formar um ângulo reto com os deles.",
"1tgybl6": "{0} tem abertura de {1}. Um portão RaceGOW cabe dentro de um quadrado de 28 in.",
"1rlgckd": "{0} tem abertura de {1}. O portão mínimo do RaceGOW é de 24 in.",
"6we35z": "{0} tem o centro da abertura de baixo a {1}. Um portão no chão tem o centro a 20 in ou menos.",
"1d69zcl": "A segunda abertura de {0} tem o centro a {1}. O portão de cima de uma pilha de dois precisa ficar a pelo menos 42 in de altura.",
"xv7gqv": "A terceira abertura de {0} tem o centro a {1}. Um terceiro portão precisa ficar a pelo menos 69 in de altura.",
"1imcxyb": "{0} chega a {1}, atravessando o teto de {2} m. Pistas RaceGOW são voadas em ambiente fechado.",
"19w4clv": "{0} empilha as aberturas a {1} uma da outra. Portões adjacentes ficam de 27 a 33 in de centro a centro, empilhados ou lado a lado.",
"1ims1cr": "{0} e {1} estão a {2} um do outro. Dois portões tão próximos são adjacentes, e portões adjacentes ficam de 27 a 33 in de centro a centro.",
"8wy7kh": "{0} e {1} estão a {2} um do outro. Se a ideia é um par lado a lado, portões adjacentes ficam de 27 a 33 in de centro a centro, nominalmente 30.",
"107lerp": "{0} está a {1} de {2}. Uma vara fica a pelo menos 14 in do centro de um portão.",
"1uyg16": "{0} e {1} estão a {2} uma da outra. Duas varas ficam a pelo menos 36 in uma da outra.",
"zolwjx": "A pista ocupa {0} por {1} m. Uma pista RaceGOW cabe em {2} por {3} m neste tamanho de portão.",
"4hr5zo": "Aperte S e clique onde a largada deve ficar.",
"lk5z4a": "A fila também fica em duas alturas: a plataforma {0} está a {1} m e a plataforma da aeronave a {2} m, então as plataformas são desenhadas a {3} m e algumas flutuam ou ficam enterradas. Mova a fila para uma superfície só.",
"ls6ln3": "As plataformas de largada ficam em duas alturas: a plataforma {0} está a {1} m e a plataforma da aeronave a {2} m. As plataformas são desenhadas a {3} m, então algumas flutuam ou ficam enterradas. Mova a fila para uma superfície só.",
"1hy0328": "{0} entra em {1}: um está construído através do outro. Mova um deles.",
"500wke": "{0} e {1} deixam uma fenda de {2} m entre eles. Um cinco polegadas precisa de {3} m para passar, então feche a fenda ou abra mais.",
"10fprle": "As pás de {0} girariam através de {1}. Mova um deles, ou gire o moinho de vento.",
"h9gzex": "{0} não é voada: um mapa voa uma só caça aos balões, {1}. Remova uma delas.",
"ym814r": "{0} tem {1} atravessando a janela, então nada passa por ela limpo. Mova o vão ou o que está nele.",
"1l0co51": "Um vão com nome",
"d008ky": "{0} está fora do terreno.",
"g0m2mr": "{0} passa da borda do terreno.",
"np34nj": "{0} está totalmente afundado no chão, então nada aparece e nada é sólido. Aumente a Base para trazer para cima.",
"2cz3wz": "Este mapa tem {0} sólidos, acima dos {1} que um mapa deve respeitar para carregar e voar bem em uma máquina lenta. O maior é {2}, com {3}.",
"1o9p6b3": "Em volta de {0} a física teria {1} formas para checar contra uma aeronave, e ela checa no máximo {2}: o resto fica de fora, e uma aeronave ali poderia atravessá-las. Afaste mais estes elementos ou use menos deles.",
"36jvfa": "{0} não tem estrada: {1}. Fica estacionado, e é desenhado na fila ao longo da borda sul do terreno. Arraste-o para uma estrada, ou exclua.",
"58628i": "{0} passa da borda do terreno.",
"kof9h3": "{0} atravessa {1}: um carro nela bateria ali. Mova a estrada, ou {2}, até um carro ter espaço para passar.",
"1x8yhyt": "{0} passa por cima das plataformas de largada, então um carro nela atravessa a aeronave que espera para decolar. Mova a estrada ou as plataformas.",
"11r26o9": "{0} passa a menos de um metro de onde a aeronave começa, então um carro nela raspa na aeronave antes de ela sair da plataforma. Mova a estrada ou as plataformas.",
"e5birv": "{0} passa por onde o piloto começa quando não há plataformas de largada, então um carro nela atravessa a aeronave. Mova a estrada, ou aperte S e coloque as plataformas de largada longe dela.",
"5s8foe": "{0} e {1} estão os dois em {2}, uma estrada aberta: todo carro anda pelo meio até o fim e de volta, então os dois se encontram de frente e atravessam um ao outro. Feche a estrada em um circuito, ou deixe só um carro nela.",
"1c7ews2": "{0} e {1} andam pela faixa única de {2} em sentidos opostos, então se encontram de frente e atravessam um ao outro. Dê duas faixas à estrada, ou inverta um deles.",
